import math

def perplexity(avg_loss, unit):
    """2**loss for "bits", e**loss for "nats"; ValueError for any other unit."""
    if unit == "bits":
        return 2 ** avg_loss
    if unit == "nats":
        return math.exp(avg_loss)
    raise ValueError("unit must be bits or nats")

